209		jsonIntegerRE = regexp.MustCompile(`^-?(0|[1-9][0-9]*)$`)
210		jsonNumberRE  = regexp.MustCompile(`^-?(0|[1-9][0-9]*)(\.[0-9]+)?([eE][+-]?[0-9]+)?$`)
211	)
