262	// QueryLine 解析并执行一行 op 为 "query" 的区间均值查询对象。成功返回 QueryResult；
263	// 查询只读，不改变存储。op 为 "query_points" 的采样明细查询由 QueryPointsLine
264	// 执行，op 为 "query_windows" 的固定窗口均值查询由 QueryWindowsLine 执行。
265	func (s *MetricStore) QueryLine(line string) (*QueryResult, *LineError) {
266		res, lerr := s.queryLineForOp(line, "query")
267		if lerr != nil {
268			return nil, lerr
269		}
270		return res.(*QueryResult), nil
271	}
