283	// QueryPointsLine 解析并执行一行 op 为 "query_points" 的区间采样明细查询对象。
284	// 成功返回 QueryPointsResult；查询只读，不改变存储。
285	func (s *MetricStore) QueryPointsLine(line string) (*QueryPointsResult, *LineError) {
286		res, lerr := s.queryLineForOp(line, "query_points")
287		if lerr != nil {
288			return nil, lerr
289		}
290		return res.(*QueryPointsResult), nil
291	}
292	
293	// queryLineForOp 是三个专用查询入口共用的请求识别骨架：整行必须是唯一完整的
294	// JSON 值且必须是查询对象（写入数组或其他顶层值一律指出需要查询对象，绝不写入
295	// 数组中的点），随后把完整合法性校验、区间检查与入口/操作匹配交给同一处
296	// runQueryObject——各入口只声明自己接受的 wantOp（"query"、"query_points" 或
297	// "query_windows"），不再各自维护解析、对象门槛与不匹配规则。成功时返回的具体
298	// 结果类型与 wantOp 对应，由调用方做类型断言；失败返回真正的 nil 与 *LineError。
299	func (s *MetricStore) queryLineForOp(line, wantOp string) (any, *LineError) {
300		top, ok, lerr := decodeTopValue(line)
301		if lerr != nil {
302			return nil, lerr
303		}
304		if ok != '{' {
305			return nil, &LineError{Status: "error", Error: "invalid JSON: input must be a query object"}
306		}
307		return s.runQueryObject(top, wantOp)
308	}
309	
310	// validateLineText 在 JSON 解析之前强制整行文本合法：原始字节必须是合法
311	// UTF-8，字符串内的 Unicode 转义必须表示有效字符。编码层/JSON 解析器会把
312	// 非法字节或未配对代理项静默替换成 U+FFFD，使损坏文本混入合法序列（被误判为
313	// 重复、冲突或错误命中查询），因此这里一律拒绝而不是修补后继续。
314	//
315	// 逐字节扫描、只在字符串内部识别转义：跳过词法空白与全部非字符串 token。
316	// 被转义的反斜杠（\\）后的 "uXXXX" 只是普通文本，不会被当成 Unicode 转义。
317	func validateLineText(line string) *LineError {
318		if !utf8.ValidString(line) {
319			return &LineError{Status: "error", Error: "invalid JSON: input is not valid UTF-8 text"}
320		}
321		inString := false
322		for i := 0; i < len(line); i++ {
323			c := line[i]
324			if !inString {
325				if c == '"' {
326					inString = true
327				}
328				continue
329			}
330			switch c {
331			case '"':
332				inString = false
333			case '\\':
334				if i+1 >= len(line) {
335					break // 悬空反斜杠：交给 JSON 解析器报错
336				}
337				if line[i+1] != 'u' {
338					i++ // 单字符转义（\\、\"、\n 等），跳过被转义字符
339					continue
340				}
341				// i 指向 '\'，i+1 指向 'u'；转义占据 i..i+5。
342				r, size := decodeJSONHexEscape(line, i+1)
343				if size == 0 {
344					return &LineError{Status: "error", Error: "invalid JSON: invalid Unicode escape sequence"}
345				}
346				if !utf16.IsSurrogate(r) {
347					i += 5
348					continue
349				}
350				if r >= 0xDC00 {
351					// 单独出现的低代理项。
352					return &LineError{Status: "error", Error: "invalid JSON: unpaired Unicode surrogate escape"}
353				}
354				// 高代理项后必须紧接另一个表示低代理项的 \uXXXX 转义。
355				loPos := i + 6 // 第一个转义之后的字符位置
356				if loPos+1 >= len(line) || line[loPos] != '\\' || line[loPos+1] != 'u' {
357					return &LineError{Status: "error", Error: "invalid JSON: unpaired Unicode surrogate escape"}
358				}
359				lo, loSize := decodeJSONHexEscape(line, loPos+1)
360				if loSize == 0 || lo < 0xDC00 || lo > 0xDFFF {
361					return &LineError{Status: "error", Error: "invalid JSON: unpaired Unicode surrogate escape"}
362				}
363				i = loPos + loSize // 跳到第二转义的最后一个十六进制位，循环自增后越出
364			}
365		}
366		return nil
367	}
368	
369	// decodeJSONHexEscape 解析 line[pos:] 处的 "uXXXX"（pos 指向 'u'），
370	// 返回其码元与占用字节数（固定为 5）；不足四个十六进制数字时 size 为 0。
371	func decodeJSONHexEscape(line string, pos int) (rune, int) {
372		if pos+4 >= len(line) {
373			return 0, 0
374		}
375		var v rune
376		for j := pos + 1; j <= pos+4; j++ {
377			c := line[j]
378			var d rune
379			switch {
380			case c >= '0' && c <= '9':
381				d = rune(c - '0')
382			case c >= 'a' && c <= 'f':
383				d = rune(c-'a') + 10
384			case c >= 'A' && c <= 'F':
385				d = rune(c-'A') + 10
386			default:
387				return 0, 0
388			}
389			v = v<<4 | d
390		}
391		return v, 5
392	}
393	
394	// decodeTopValue 解析单行中唯一的 JSON 值并返回其原始内容与首个非空白字节
395	// （'[' 或 '{'）。整个值无法解析、为空或存在尾随内容时返回 *LineError。
396	func decodeTopValue(line string) (json.RawMessage, byte, *LineError) {
397		if lerr := validateLineText(line); lerr != nil {
398			return nil, 0, lerr
399		}
400		dec := json.NewDecoder(strings.NewReader(line))
401		var top json.RawMessage
402		if err := dec.Decode(&top); err != nil {
403			return nil, 0, &LineError{Status: "error", Error: "invalid JSON: " + err.Error()}
404		}
405		// 第一个 JSON 值之后只允许输入结束（Decoder 自动跳过尾随空白）。
406		if err := dec.Decode(new(json.RawMessage)); err != io.EOF {
407			if err == nil {
408				err = fmt.Errorf("unexpected content after the JSON value")
409			}
410			return nil, 0, &LineError{Status: "error", Error: "invalid JSON: " + err.Error()}
411		}
412		trimmed := strings.TrimSpace(string(top))
413		if len(trimmed) == 0 || (trimmed[0] != '[' && trimmed[0] != '{') {
414			return nil, 0, &LineError{Status: "error", Error: "invalid JSON: input must be a JSON array of samples or a query object"}
415		}
416		return top, trimmed[0], nil
417	}
418	
419	// fieldReader 从 dec 读取并校验当前字段的值，写入调用方持有的结果。
420	// 采样点与查询对象各自注册自己允许的字段及字段含义。
421	type fieldReader func(dec *json.Decoder) error
422	
423	// parseStrictObject 是写入采样点与查询对象共用的严格对象校验骨架：
424	// 仅允许 fields 中列出的字段（未知字段先于判重被拒绝），同一对象内按转义还原
425	// 后的字段名判重（即使两个值相同也拒绝；判重不跨对象、不跨层级），按输入次序
426	// 逐字段调用对应的 fieldReader，对象结束后要求输入恰好耗尽，最后按 required
427	// 的顺序报告缺失的必填字段。notObjectMsg 与 trailingMsg 由调用方给出，
428	// 保留各自输入的措辞。
429	func parseStrictObject(raw json.RawMessage, notObjectMsg, trailingMsg string, required []string, fields map[string]fieldReader) error {
430		dec := json.NewDecoder(bytes.NewReader(raw))
431		dec.UseNumber()
432	
433		tok, err := dec.Token()
434		if err != nil {
435			return err
436		}
437		if d, ok := tok.(json.Delim); !ok || d != '{' {
438			return fmt.Errorf("%s", notObjectMsg)
439		}
440	
441		present := make(map[string]bool)
442		for dec.More() {
443			keyTok, err := dec.Token()
444			if err != nil {
445				return err
446			}
447			key := keyTok.(string)
448			read, ok := fields[key]
449			if !ok {
450				return fmt.Errorf("unknown field %q", key)
451			}
452			if present[key] {
453				return fmt.Errorf("duplicate field %q", key)
454			}
455			present[key] = true
456			if err := read(dec); err != nil {
457				return err
458			}
459		}
460		if _, err := dec.Token(); err != nil { // 消耗 '}'
461			return err
462		}
463		if _, err := dec.Token(); err != io.EOF {
464			if err == nil {
465				return fmt.Errorf("%s", trailingMsg)
466			}
467			return err
468		}
469	
470		for _, field := range required {
471			if !present[field] {
472				return fmt.Errorf("missing required field %q", field)
473			}
474		}
475		return nil
476	}
477	
478	// readNameField 读取写入与查询共用的指标名字段：必须是非空字符串。
479	func readNameField(dec *json.Decoder, dst *string) error {
480		t, err := dec.Token()
481		if err != nil {
482			return err
483		}
484		s, ok := t.(string)
485		if !ok {
486			return fmt.Errorf(`field "name" must be a string`)
487		}
488		if s == "" {
489			return fmt.Errorf(`field "name" must be a non-empty string`)
490		}
491		*dst = s
492		return nil
493	}
494	
495	// readInt64Field 读取 int64 毫秒整数字段（timestamp/start/end）：
496	// 必须是 JSON 整数且在 int64 范围内，数字字符串、布尔值、带小数点一律拒绝。
497	func readInt64Field(dec *json.Decoder, field string, dst *int64) error {
498		n, err := nextJSONNumber(dec, field)
499		if err != nil {
500			return err
501		}
502		v, err := parseJSONInt(n)
503		if err != nil {
504			return fmt.Errorf("field %q: %s", field, err)
505		}
506		*dst = v
507		return nil
508	}
509	
510	// readFiniteFloatField 读取采样值字段：必须是可表示为有限 float64 的 JSON 数字。
511	func readFiniteFloatField(dec *json.Decoder, field string, dst *float64) error {
512		n, err := nextJSONNumber(dec, field)
513		if err != nil {
514			return err
515		}
516		v, err := parseFiniteFloat(n)
517		if err != nil {
518			return fmt.Errorf("field %q: %s", field, err)
519		}
520		*dst = v
521		return nil
522	}
523	
524	// readLabelsField 读取标签对象字段并写入 dst；notObjectMsg 保留各输入侧措辞。
525	func readLabelsField(dec *json.Decoder, notObjectMsg string, dst *map[string]string) error {
526		labels, err := parseLabels(dec, notObjectMsg)
527		if err != nil {
528			return err
529		}
530		*dst = labels
531		return nil
532	}
533	
534	type parsedSample struct {
535		name   string
536		ts     int64
537		value  float64
538		labels map[string]string
539	}
540	
541	// parseSample 对单个采样点做严格校验：仅允许四个已知字段、拒绝重复键，
542	// 标量必须是精确的 JSON 类型，timestamp 为 int64 整数，value 为有限 float64。
543	func parseSample(raw json.RawMessage) (parsedSample, error) {
544		var p parsedSample
545		p.labels = map[string]string{}
546		err := parseStrictObject(raw,
547			"each sample must be a JSON object",
548			"unexpected content after the sample object",
549			[]string{"name", "timestamp", "value"},
550			map[string]fieldReader{
551				"name":      func(dec *json.Decoder) error { return readNameField(dec, &p.name) },
552				"timestamp": func(dec *json.Decoder) error { return readInt64Field(dec, "timestamp", &p.ts) },
553				"value":     func(dec *json.Decoder) error { return readFiniteFloatField(dec, "value", &p.value) },
554				"labels": func(dec *json.Decoder) error {
555					return readLabelsField(dec, `field "labels" must be an object of string keys to string values`, &p.labels)
556				},
557			})
558		return p, err
559	}
560	
561	// parseLabels 从 dec 读取一个标签对象并做统一校验：必须是 JSON 对象
562	// （否则返回调用方给出的 notObjectMsg，写入与查询措辞不同），键为非空字符串、
563	// 值为字符串（空串合法，键值均不做清理），重复键一律拒绝。
564	// 判重先于值的类型校验：某个键第一次出现时若值不是字符串，仍报告该值的类型
565	// 错误；而该键再次出现时，无论第二次的值是什么（数字、布尔、null、对象、数组），
566	// 都先报告重复标签键，不能让第二次值的类型掩盖键重复。
567	// 返回的集合不含标签时也是非 nil 的空 map，与省略 labels 的语义一致。
568	func parseLabels(dec *json.Decoder, notObjectMsg string) (map[string]string, error) {
569		t, err := dec.Token()
570		if err != nil {
571			return nil, err
572		}
573		d, ok := t.(json.Delim)
574		if !ok || d != '{' {
575			return nil, fmt.Errorf("%s", notObjectMsg)
576		}
577		labels := map[string]string{}
578		for dec.More() {
579			labelKeyTok, err := dec.Token()
580			if err != nil {
581				return nil, err
582			}
583			labelKey := labelKeyTok.(string)
584			if labelKey == "" {
585				return nil, fmt.Errorf(`field "labels": label keys must be non-empty strings`)
586			}
587			// 先判重再读值：与采样点/查询字段的判重一致，重复键不被值的类型掩盖。
588			if _, dup := labels[labelKey]; dup {
589				return nil, fmt.Errorf(`field "labels": duplicate label key %q`, labelKey)
590			}
591			valTok, err := dec.Token()
592			if err != nil {
593				return nil, err
594			}
595			labelVal, ok := valTok.(string)
596			if !ok {
597				return nil, fmt.Errorf(`field "labels": value of label %q must be a string`, labelKey)
598			}
599			labels[labelKey] = labelVal
600		}
601		if _, err := dec.Token(); err != nil { // 消耗 '}'
602			return nil, err
603		}
604		return labels, nil
605	}
606	
607	func nextJSONNumber(dec *json.Decoder, field string) (json.Number, error) {
608		t, err := dec.Token()
609		if err != nil {
610			return "", err
611		}
612		n, ok := t.(json.Number)
613		if !ok {
614			return "", fmt.Errorf(`field %q must be a JSON number`, field)
615		}
616		return n, nil
617	}
618	
619	func parseJSONInt(n json.Number) (int64, error) {
620		s := string(n)
621		if !jsonIntegerRE.MatchString(s) {
622			return 0, fmt.Errorf("must be a JSON integer in milliseconds")
623		}
624		v, err := strconv.ParseInt(s, 10, 64)
625		if err != nil {
626			return 0, fmt.Errorf("must be within int64 range")
627		}
628		return v, nil
629	}
630	
631	func parseFiniteFloat(n json.Number) (float64, error) {
632		s := string(n)
633		if !jsonNumberRE.MatchString(s) {
634			return 0, fmt.Errorf("must be a JSON number")
635		}
636		v, err := strconv.ParseFloat(s, 64)
637		if err != nil || math.IsInf(v, 0) || math.IsNaN(v) {
638			return 0, fmt.Errorf("must be a finite number representable as float64")
639		}
640		return v, nil
641	}
642	
643	// ingestItems 完成全部采样点校验与冲突检测后再统一提交，保证整批原子性。
644	func (s *MetricStore) ingestItems(items []json.RawMessage) (*BatchResult, *LineError) {
645		type pending struct {
646			id  seriesID
647			ref SeriesRef
648			ts  int64
649			val float64
650		}
651	
652		added := 0
653		// 本批已确定身份的点（含与已写入数据重复的点），用于批内去重与冲突检测。
654		seen := make(map[seriesID]map[int64]float64)
655		// 仅记录需要落盘的新增点；校验全部通过后才提交。
656		commits := make([]pending, 0, len(items))
657	
658		failAt := func(index int, msg string) *LineError {
659			return &LineError{Status: "error", Index: index, Error: msg}
660		}
661		conflictAt := func(index int, ref SeriesRef, ts int64, existing, submitted float64) *LineError {
662			return &LineError{
663				Status: "error",
664				Index:  index,
665				Error: fmt.Sprintf("conflict: series %s at timestamp %d already has value %s, submitted %s",
666					ref, ts, formatFloat(existing), formatFloat(submitted)),
667				Conflict: &Conflict{
668					// 标签必须复制：冲突结果是本次失败的独立记录，
669					// 调用方修改它不能改动已存序列的身份。
670					Series:    SeriesRef{Name: ref.Name, Labels: cloneLabels(ref.Labels)},
671					Timestamp: ts,
672					Existing:  existing,
673					Submitted: submitted,
674				},
675			}
676		}
677	
678		for i, item := range items {
679			pos := i + 1
680			p, err := parseSample(item)
681			if err != nil {
682				return nil, failAt(pos, err.Error())
683			}
684	
685			id := makeSeriesID(p.name, p.labels)
686			ref := SeriesRef{Name: p.name, Labels: p.labels}
687	
688			// 同一采样位置无论值来自本批较早接受的点还是此前批次已写入的点，
689			// 都走同一条判定：转换后的 float64 相等即重复、成功忽略，不同即冲突、
690			// 整批拒绝。existing 是该位置当前生效的值，两种来源下语义一致。
691			if existing, ok := s.positionValue(seen, id, p.ts); ok {
692				if existing != p.value {
693					return nil, conflictAt(pos, ref, p.ts, existing, p.value)
694				}
695				// 等值重复：成功忽略。seen 记录的是生效值 existing 而不是本次
696				// 提交的 p.value：数值相等但表示不同（如已存 -0、本次提交 +0）时，
697				// 本批后续在同位置的冲突必须如实报告最先接受的值，
698				// 不能被这条被忽略的重复改写。
699				if seen[id] == nil {
700					seen[id] = map[int64]float64{}
701				}
702				seen[id][p.ts] = existing
703				continue
704			}
705	
706			added++
707			if seen[id] == nil {
708				seen[id] = map[int64]float64{}
709			}
710			seen[id][p.ts] = p.value
711			commits = append(commits, pending{id: id, ref: ref, ts: p.ts, val: p.value})
712		}
713	
714		// 全部采样点合法且无冲突，原子提交本批新增点。
715		for _, c := range commits {
716			sr := s.series[c.id]
717			if sr == nil {
718				sr = &storedSeries{ref: c.ref, points: map[int64]float64{}}
719				s.series[c.id] = sr
720			}
721			sr.points[c.ts] = c.val
722		}
723	
724		return s.snapshot(added, len(items)-added), nil
725	}
726	
727	// positionValue 解析一个采样位置（序列身份 + 时间戳）当前生效的值：
728	// 本批已接受的值优先（含与已写入数据等值而被忽略的重复所登记的生效值），
729	// 其次是此前批次已成功写入的值；该位置没有任何数据时 ok 为 false。
730	// 重复与冲突判定只看这里返回的值，不再区分两种来源。
731	func (s *MetricStore) positionValue(seen map[seriesID]map[int64]float64, id seriesID, ts int64) (value float64, ok bool) {
732		if byTS, found := seen[id]; found {
733			if v, hit := byTS[ts]; hit {
734				return v, true
735			}
736		}
737		if sr, found := s.series[id]; found {
738			if v, hit := sr.points[ts]; hit {
739				return v, true
740			}
741		}
742		return 0, false
743	}
744	
745	// formatFloat 以 JSON 数值风格格式化 float64：1 与 1.0 均显示为 1。
746	func formatFloat(v float64) string {
747		return strconv.FormatFloat(v, 'g', -1, 64)
748	}
749	
750	type parsedQuery struct {
751		op        string
752		name      string
753		start     int64
754		end       int64
755		labels    map[string]string
756		step      int64
757		stepGiven bool
758		// basicGiven 记录 op/name/start/end 四个基础字段是否在对象中出现过：
759		// 必填检查不能用零值判断（0 与空串可能就是合法输入）。
760		basicGiven map[string]bool
761	}
762	
763	// runQueryObject 严格解析查询对象并执行对应的只读操作：op 为 "query" 时
764	// 统计区间内点数与均值，为 "query_points" 时列出区间内采样明细，为
765	// "query_windows" 时按固定宽度时间窗口分别统计点数与均值。
766	//
767	// 统一入口 ProcessLine/ingest 传 wantOp 为空：按请求自身的 op 选择查询功能，
768	// 不做入口匹配。三个专用查询入口分别传 "query"、"query_points"、
769	// "query_windows"：仅在请求全部字段合法、必填齐全且区间合法之后才比较 op 与
770	// wantOp——在此之前，请求自身的字段错误、缺项、未知字段/未知 op 与倒置区间
771	// 一律先报请求自身的原因；完整合法但 op 不符时只返回错误，原因由
772	// wrongQueryEntryError 集中给出：说明该 op 提供什么结果、应改用哪个公开入口，
773	// 绝不返回另一类查询的结果，也不把不匹配当作无命中的成功。
774	// 成功返回非 nil 的 *QueryResult、*QueryPointsResult 或 *QueryWindowsResult；
775	// 失败返回 nil 与 *LineError。查询只读，不改变存储。
776	func (s *MetricStore) runQueryObject(raw json.RawMessage, wantOp string) (any, *LineError) {
777		q, err := parseQuery(raw)
778		if err != nil {
779			return nil, &LineError{Status: "error", Error: err.Error()}
780		}
781		if q.op == "query_windows" && !q.stepGiven {
782			return nil, &LineError{Status: "error", Error: `missing required field "step"`}
783		}
784		if q.start > q.end {
785			return nil, &LineError{Status: "error", Error: fmt.Sprintf(
786				`invalid range: "start" must not be greater than "end" (%d > %d)`, q.start, q.end)}
787		}
788		// 请求至此已完整合法；专用入口若与请求自身的 op 不符，只报告入口不匹配，
789		// 不执行任何查询（不返回另一类结果，也不产生空命中）。统一入口 wantOp 为空，
790		// 跳过匹配。措辞集中在 wrongQueryEntryError 一处维护。
791		if wantOp != "" && q.op != wantOp {
792			return nil, wrongQueryEntryError(q.op)
793		}
794		switch q.op {
795		case "query_points":
796			return s.runQueryPoints(q), nil
797		case "query_windows":
798			return s.runQueryWindows(q), nil
799		default:
800			return s.runQuery(q), nil
801		}
802	}
803	
804	// wrongQueryEntryError 是三种专用查询入口共用的唯一“操作与入口不匹配”措辞来源：
805	// 按请求自身携带的 op 说明该操作提供什么结果、应改用哪个公开入口。调用方保证
806	// op 是三个受支持操作之一（完整合法的请求才能走到这里），且与入口接受的操作
807	// 不同。消息文本只依赖 op，因此同一操作在任何入口被拒绝时的原因完全一致，
808	// 不需要在各入口分别维护两条分支。
809	func wrongQueryEntryError(op string) *LineError {
810		var msg string
811		switch op {
812		case "query_points":
813			msg = `op "query_points" lists sample points; use QueryPointsLine`
814		case "query_windows":
815			msg = `op "query_windows" lists fixed-window averages; use QueryWindowsLine`
816		default: // "query"
817			msg = `op "query" computes range statistics; use QueryLine`
818		}
819		return &LineError{Status: "error", Error: msg}
820	}
821	
822	// parseQuery 对查询对象做严格校验：仅允许 op/name/start/end/labels，
823	// 以及仅 query_windows 使用的 step；拒绝重复键与未知字段；标量必须是精确的
824	// JSON 类型，start/end 为 int64 毫秒。op 只接受 "query"（区间点数与均值）、
825	// "query_points"（区间采样明细）与 "query_windows"（固定窗口均值），三种操作
826	// 共用同一套字段校验与区间规则。
827	//
828	// 错误选择沿用既有次序：结构完整的对象按字段书写顺序暴露问题，已出现字段全部
829	// 合法后才按 op、name、start、end 的顺序报告缺失的必填字段（step 是否必填要
830	// 等 op 确定，其缺失由 runQueryObject 在四项必填齐全后判定）。step 是否合法
831	// 由操作本身决定，与 op 的书写位置无关：先用 decidedQueryOp 预扫对象，op 恰好
832	// 出现一次且为受支持操作时即已确定——query 与 query_points 携带 step 一律是
833	// 未知字段，无论 step 写在 op 前后、值是正整数、零、字符串还是对象，都在 step
834	// 自己的书写位置按未知字段拒绝，绝不退化成窗口宽度校验；query_windows 的 step
835	// 在出现处即按 JSON 正整数校验：int64 范围、大于零，缺失、类型不符或值不合法
836	// 都指出 step。op 缺失、重复、类型不符或取值未知时无法据此判定 step，回退到
837	// 既有行为：step 在出现处按窗口宽度校验，op 自身的问题仍按书写次序暴露。
838	func parseQuery(raw json.RawMessage) (parsedQuery, error) {
839		var q parsedQuery
840		q.basicGiven = map[string]bool{}
841		decidedOp := decidedQueryOp(raw)
842		err := parseStrictObject(raw,
843			"each query must be a JSON object",
844			"unexpected content after the query object",
845			nil,
846			map[string]fieldReader{
847				"op": func(dec *json.Decoder) error {
848					q.basicGiven["op"] = true
849					t, err := dec.Token()
850					if err != nil {
851						return err
852					}
853					op, ok := t.(string)
854					if !ok {
855						return fmt.Errorf(`field "op" must be a string`)
856					}
857					if op != "query" && op != "query_points" && op != "query_windows" {
858						return fmt.Errorf(`unknown op %q (only "query", "query_points" and "query_windows" are supported)`, op)
859					}
860					q.op = op
861					return nil
862				},
863				"name": func(dec *json.Decoder) error {
864					q.basicGiven["name"] = true
865					return readNameField(dec, &q.name)
866				},
867				"start": func(dec *json.Decoder) error {
868					q.basicGiven["start"] = true
869					return readInt64Field(dec, "start", &q.start)
870				},
871				"end": func(dec *json.Decoder) error {
872					q.basicGiven["end"] = true
873					return readInt64Field(dec, "end", &q.end)
874				},
875				"labels": func(dec *json.Decoder) error {
876					return readLabelsField(dec, `field "labels" must be an object of non-empty string keys to string values`, &q.labels)
877				},
878				"step": func(dec *json.Decoder) error {
879					// 操作已确定且不是 query_windows：对该操作 step 是未知字段，
880					// 不读其值，直接按书写次序拒绝（与 parseStrictObject 的未知字段
881					// 处理一致）。确定的途径有两种：op 已写在 step 之前并成功读取
882					// （q.op），或预扫发现 op 恰好出现一次且为受支持操作
883					// （decidedOp，覆盖 step 写在 op 之前的情形）——两种途径下
884					// step 的值都无关紧要，正整数、零、字符串、对象同样拒绝。
885					if q.op != "" && q.op != "query_windows" {
886						return fmt.Errorf(`unknown field "step"`)
887					}
888					if decidedOp == "query" || decidedOp == "query_points" {
889						return fmt.Errorf(`unknown field "step"`)
890					}
891					if err := readInt64Field(dec, "step", &q.step); err != nil {
892						return err
893					}
894					if q.step <= 0 {
895						return fmt.Errorf(`field "step": must be greater than zero`)
896					}
897					q.stepGiven = true
898					return nil
899				},
900			})
901		if err != nil {
902			return q, err
903		}
904		// op 写在 step 之后时，读完对象才知道 step 对该 op 是否合法；该判定属于
905		// “已出现字段的合法性”，必须先于下面的必填字段缺失检查。op 本身缺失时不在这里
906		// 判定 step 未知——请求可能是漏写 op 的 query_windows，交给下面的固定必填次序
907		// 先报告 op（与“缺字段检查先于区间检查”等既有选择规则一致）。
908		if q.stepGiven && q.op != "" && q.op != "query_windows" {
909			return q, fmt.Errorf(`unknown field "step"`)
910		}
911		// 必填项固定按 op、name、start、end 的顺序报告第一个缺项，与字段书写位置无关。
912		for _, field := range []string{"op", "name", "start", "end"} {
913			if !q.basicGiven[field] {
914				return q, fmt.Errorf("missing required field %q", field)
915			}
916		}
917		return q, nil
918	}
919	
920	// decidedQueryOp 预扫查询对象的顶层字段，确定用于判定 step 是否合法的操作：
921	// op 恰好出现一次且取值是三个受支持操作之一时返回该操作；其余情况（op 缺失、
922	// 重复出现、不是字符串或取值未知）返回空串，表示无法据此判定，step 的校验
923	// 回退到按窗口宽度进行的既有行为。预扫只读不写：字段的逐项校验与错误暴露
924	// 仍由 parseStrictObject 按书写次序完成，op 自身的类型错误、未知取值与重复
925	// 出现都在 op 的书写位置按既有措辞报告。键名比较与 parseStrictObject 一样
926	// 在转义还原后进行，因此以转义形式书写的 op 同样被识别。
927	func decidedQueryOp(raw json.RawMessage) string {
928		dec := json.NewDecoder(bytes.NewReader(raw))
929		tok, err := dec.Token()
930		if err != nil {
931			return ""
932		}
933		if d, ok := tok.(json.Delim); !ok || d != '{' {
934			return ""
935		}
936		op := ""
937		opCount := 0
938		for dec.More() {
939			keyTok, err := dec.Token()
940			if err != nil {
941				return ""
942			}
943			key, _ := keyTok.(string)
944			var value json.RawMessage
945			if err := dec.Decode(&value); err != nil {
946				return ""
947			}
948			if key != "op" {
949				continue
950			}
951			opCount++
952			var s string
953			if err := json.Unmarshal(value, &s); err != nil {
954				return ""
955			}
956			op = s
957		}
958		if opCount != 1 {
959			return ""
960		}
961		switch op {
962		case "query", "query_points", "query_windows":
963			return op
964		}
965		return ""
966	}
