	if labels != nil {
		b.WriteString(`,"labels":`)
		b.WriteString(jsonLabels(labels))
	}
	b.WriteByte('}')
	return b.String()
}

// jsonLabels 把标签集合编码为 JSON 对象文本（Go 按键排序输出，身份与顺序无关）。
func jsonLabels(labels map[string]string) string {
	b, _ := json.Marshal(labels)
	return string(b)
}

// jsonString 把单个字符串编码为 JSON 字符串文本。
func jsonString(s string) string {
	b, _ := json.Marshal(s)
	return string(b)
}

	}
	s := queryOne(t, store, queryAll("m", tsMinInt64, tsMaxInt64))
	assertSeriesStats(t, s, "m", map[string]string{}, 3, 5, "full range after failures")
}

// marshalCompact 把查询结果编码为紧凑 JSON 文本，用于锁定空结果形状。
func marshalCompact(t *testing.T, v any) string {
	t.Helper()
	b, err := json.Marshal(v)
	if err != nil {
		t.Fatalf("marshal: %v", err)
	}
	return string(b)
}

