	pointsByLabels := map[int]int{}
	for _, e := range snap["series"].([]interface{}) {
		sm := e.(map[string]interface{})
		pointsByLabels[len(sm["labels"].(map[string]interface{}))] = len(sm["points"].([]interface{}))
